package com.cornealai.backend.analysis.storage;

/**
 * Server-side image storage. Object paths are always generated by the backend;
 * clients only ever hold an image id that the backend resolves after checking access.
 */
public interface ImageStorage {

    /** Bucket the objects are written to (recorded with each image). */
    String bucket();

    void store(String objectPath, byte[] data, String contentType);

    byte[] read(String objectPath);

    void delete(String objectPath);
}
